            try {
                showToast(nxForce3d()
                    ? '3D включён вручную: проверяем после перезагрузки. Если игра упадёт — оно само снова перейдёт в плоский режим'
                    : '3D выключен: игры работают в плоском, но надёжном режиме', 'success');
            } catch (e) {}
