                const W = 300, H = 400;
                const cv = document.createElement('canvas');
                cv.width = W; cv.height = H;
                const g = cv.getContext('2d');
                if (!g) return '';
                const pal = {
                    common: ['#475569', '#0f172a'], rare: ['#2563eb', '#1e1b4b'],
                    epic: ['#9333ea', '#2e1065'], legendary: ['#f59e0b', '#451a03']
                }[card.rarity] || ['#475569', '#0f172a'];
